import java.util.Map;

public class ClassX {
    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     *
     * @param header El mapa que representa el encabezado del token, donde las claves son los nombres de los campos
     *               y los valores son los valores de los campos.
     * @return {@code true} si el campo 'alg' existe y su valor es 'HS256'; {@code false} en caso contrario
     *         (por ejemplo, si el encabezado es nulo, está vacío, no contiene 'alg', o 'alg' tiene un valor diferente).
     */
    public boolean validateTokenHeader(Map<String, String> header) {
        if (header == null || header.isEmpty()) {
            return false;
        }
        String algorithm = header.get("alg");
        return "HS256".equals(algorithm);
    }
}
```

