import java.util.Map;

public class ClassX {
    /**
     * Tinitiyak ng function na ito ang header ng token upang matiyak na sinusuportahan ang algorithm.
     *
     * Sinusuri ng function kung ang 'alg' na larangan sa header ay naglalaman ng 'HS256'.
     *
     * @param tokenHeader Ang header ng token, na karaniwang naglalaman ng mga key-value pairs tulad ng "alg".
     * @throws IllegalArgumentException Kung ang 'alg' na larangan ay hindi 'HS256' o nawawala.
     */
    public void ensureAlgorithmSupported(Map<String, String> tokenHeader) {
        if (tokenHeader == null || !tokenHeader.containsKey("alg")) {
            throw new IllegalArgumentException("Token header must contain 'alg' field.");
        }

        String algorithm = tokenHeader.get("alg");
        if (!"HS256".equals(algorithm)) {
            throw new IllegalArgumentException("Unsupported algorithm: " + algorithm + ". Only 'HS256' is supported.");
        }
    }
}
