import java.io.File;

public class ClassX {
    /**
     * يستخرج عضوًا محددًا من أرشيف (محاكاة).
     * 
     * تتحقق الدالة مما إذا كان اسم العضو يبدأ بشرطة مائلة لمنع المسارات المطلقة.
     *
     * @param memberName اسم العضو المراد استخراجه.
     * @return سلسلة نصية تمثل محتوى العضو المستخرج (محاكاة).
     * @throws IllegalArgumentException إذا كان اسم العضو يبدأ بشرطة مائلة أو كان فارغًا/null.
     */
    public String extractMember(String memberName) {
        if (memberName == null || memberName.trim().isEmpty()) {
            throw new IllegalArgumentException("Member name cannot be null or empty.");
        }
        if (memberName.startsWith("/") || memberName.startsWith("\\")) {
            throw new IllegalArgumentException("Member name cannot start with a slash or backslash to prevent absolute paths.");
        }

        // Simulate the extraction process
        System.out.println("Simulating extraction of member: " + memberName);
        return "Simulated content for: " + memberName;
    }

    public static void main(String[] args) {
        ClassX archiver = new ClassX();

        // Valid cases
        try {
            System.out.println(archiver.extractMember("document.pdf"));
            System.out.println(archiver.extractMember("folder/image.jpg"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        System.out.println("\n--- Testing invalid cases ---");

        // Invalid cases
        try {
            System.out.println(archiver.extractMember("/etc/passwd"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        try {
            System.out.println(archiver.extractMember("\\windows\\system32\\config"));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        try {
            System.out.println(archiver.extractMember(""));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        try {
            System.out.println(archiver.extractMember(null));
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
