     *                  If null, an empty string will be used as user input.
     * @return The rendered template with the sanitized user input.
     */
    public String renderTemplateWithSanitizedInput(String template, String userInput) {
        // Handle null inputs gracefully to prevent NullPointerExceptions
        String safeTemplate = (template == null) ? "" : template;
        String safeUserInput = (userInput == null) ? "" : userInput;

        // 1. Sanitize the user input by blocking Jinja2 variable delimiters.
        // Replace '{{' and '}}' with an empty string to prevent them from being interpreted
        // as template variables or control structures.
        String sanitizedInput = safeUserInput.replace("{{", "").replace("}}", "");

        // 2. Render the template by replacing a specific placeholder with the sanitized input.
        // This example assumes a placeholder like "[USER_INPUT]". In a real application,
        // this might be integrated with a more sophisticated templating mechanism.
        String renderedTemplate = safeTemplate.replace("[USER_INPUT]", sanitizedInput);

        return renderedTemplate;
    }
