    public String renderTemplateWithUserInput(String template, String userInput) {
        // Sanitize the user input to prevent Jinja2 variable delimiters from being interpreted.
        // A common approach is to replace the delimiters with a slightly modified version
        // that won't be recognized by the templating engine, e.g., by adding a space or
