public class ClassX {
    /**
     * Αποδίδει ένα πρότυπο που περιλαμβάνει την είσοδο του χρήστη.
     *
     * Η συνάρτηση προσπαθεί να καθαρίσει την είσοδο αποκλείοντας τους διαχωριστές μεταβλητών Jinja2.
     *
     * @param template Το πρότυπο στο οποίο θα ενσωματωθεί η είσοδος του χρήστη.
     *                 Αναμένεται να περιέχει ένα placeholder όπως "{user_input}".
     * @param userInput Η είσοδος του χρήστη που θα καθαριστεί και θα ενσωματωθεί.
     * @return Το αποδοθέν πρότυπο με την καθαρισμένη είσοδο του χρήστη.
     */
    public String renderTemplateWithUserInput(String template, String userInput) {
        if (template == null || userInput == null) {
            throw new IllegalArgumentException("Template and user input cannot be null.");
        }

        // Καθαρισμός της εισόδου του χρήστη από τους διαχωριστές μεταβλητών Jinja2
        // (π.χ., {{ και }}) για να αποφευχθεί η ακούσια απόδοση ή η έγχυση.
        String cleanedInput = userInput.replace("{{", "")
                                       .replace("}}", "");

        // Ενσωμάτωση της καθαρισμένης εισόδου στο πρότυπο.
        // Υποθέτουμε ότι το πρότυπο έχει ένα placeholder όπως "{user_input}".
        return template.replace("{user_input}", cleanedInput);
    }
}
