public class ClassX {
    /**
     * Rendert eine Vorlage, die Benutzereingaben enthält.
     * 
     * Die Funktion versucht, die Eingabe zu bereinigen, indem sie Jinja2-Variablenbegrenzer blockiert.
     */
    private static final String JINJA2_VAR_START = "{{";
    private static final String JINJA2_VAR_END = "}}";
    private static final String SANITIZED_REPLACEMENT = "[BLOCKED]"; // Or an HTML-escaped version

    /**
     * Renders a template string, incorporating user input after sanitizing it
     * to prevent Jinja2 template injection.
     *
     * @param template The base template string, e.g., "Hello, {name}!".
     *                 This example assumes a simple placeholder like "{name}"
     *                 for the sanitized user input. In a real scenario,
     *                 a proper templating engine would be used.
     * @param userInput The raw user-provided string that needs to be inserted into the template.
     * @return The rendered string with the sanitized user input.
     */
    public String renderTemplateWithSanitizedInput(String template, String userInput) {
        String sanitizedInput = sanitizeUserInput(userInput);
        // This is a very basic placeholder replacement.
        // A real templating engine would be more sophisticated.
        return template.replace("{name}", sanitizedInput);
    }

    /**
     * Sanitizes a given string by replacing Jinja2 variable delimiters
     * ({{ and }}) with a safe replacement string.
     *
     * @param input The string to sanitize.
     * @return The sanitized string.
     */
    private String sanitizeUserInput(String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }
        String result = input.replace(JINJA2_VAR_START, SANITIZED_REPLACEMENT);
        result = result.replace(JINJA2_VAR_END, SANITIZED_REPLACEMENT);
        return result;
    }

    // Example usage (optional, for demonstration)
    public static void main(String[] args) {
        ClassX renderer = new ClassX();
        String template = "Hello, {name}! Welcome to our service.";

        String safeInput = "John Doe";
        String maliciousInput = "John Doe {{ config.items() }}";
        String anotherMaliciousInput = "Jane Smith }} malicious content {{";

        System.out.println("Safe Render: " + renderer.renderTemplateWithSanitizedInput(template, safeInput));
        System.out.println("Malicious Render 1: " + renderer.renderTemplateWithSanitizedInput(template, maliciousInput));
        System.out.println("Malicious Render 2: " + renderer.renderTemplateWithSanitizedInput(template, anotherMaliciousInput));
    }
}
