    /**
     * Renderdab mallist, mis sisaldab kasutaja sisendit.
     * 
     * Funktsioon püüab sisendit puhastada, blokeerides Jinja2 muutuja
     * piirajad.
     *
     * @param template Malli string, mis sisaldab kohti kasutaja sisendi jaoks.
     * @param userInput Kasutaja sisend, mis tuleb malli lisada.
     * @return Renderdatud string, kus kasutaja sisend on puhastatud ja malli lisatud.
     */
    public String renderTemplateWithCleanedInput(String template, String userInput) {
        // Puhasta kasutaja sisend, blokeerides Jinja2 muutuja piirajad.
        // Asendame '{{' ja '}}' HTML-entiteetidega, et vältida nende tõlgendamist
        // Jinja2 mallimootori poolt, kui see peaks hiljem uuesti töödeldama.
        String cleanedInput = userInput
                .replace("{{", "&#123;&#123;") // Asendab '{{' HTML-entiteetidega
                .replace("}}", "&#125;&#125;"); // Asendab '}}' HTML-entiteetidega

        // Lihtne näide malli renderdamisest.
        // Eeldame, et mallis on koht, kuhu sisend lisada, näiteks "{user_content}".
        // Tegelikus rakenduses oleks siin keerulisem mallimootori loogika,
        // mis võtaks arvesse malli struktuuri ja sisendi paigutust.
        return template.replace("{user_content}", cleanedInput);
    }
}

