import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     * 
     * @param host The hostname or IP address to ping.
     * @return A string containing the ping output, or an error message if the input is invalid or an error occurs.
     */
    public String pingHost(String host) {
        // Input sanitization: Block semicolons and ampersands
        if (host == null || host.isEmpty()) {
            return "Error: Host cannot be null or empty.";
        }
        if (host.contains(";") || host.contains("&") || host.contains("|") || host.contains("`") || host.contains("$")) {
            return "Error: Invalid characters detected in host. Semicolons, ampersands, pipes, backticks, and dollar signs are not allowed.";
        }

        StringBuilder output = new StringBuilder();
        Process process = null;
        BufferedReader reader = null;

        try {
            // Determine OS and construct the ping command
            String osName = System.getProperty("os.name").toLowerCase();
            String command;
            if (osName.contains("win")) {
                // Windows command: ping -n 4 <host>
                command = "ping -n 4 " + host;
            } else {
                // Unix/Linux/macOS command: ping -c 4 <host>
                command = "ping -c 4 " + host;
            }

            process = Runtime.getRuntime().exec(command);

            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Also read error stream in case of issues
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                output.append("Ping command exited with code: ").append(exitCode).append("\n");
            }

        } catch (IOException e) {
            output.append("Error executing ping command: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Ping command was interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    // Log or handle closing error
                    output.append("Error closing reader: ").append(e.getMessage()).append("\n");
                }
            }
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }
        return output.toString();
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Pinging google.com ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Pinging a non-existent host (example.invalid) ---");
        System.out.println(pinger.pingHost("example.invalid"));

        System.out.println("\n--- Attempting to ping with invalid characters (google.com; ls) ---");
        System.out.println(pinger.pingHost("google.com; ls"));

        System.out.println("\n--- Attempting to ping with invalid characters (google.com & ls) ---");
        System.out.println(pinger.pingHost("google.com & ls"));

        System.out.println("\n--- Attempting to ping with empty host ---");
        System.out.println(pinger.pingHost(""));

        System.out.println("\n--- Attempting to ping with null host ---");
        System.out.println(pinger.pingHost(null));
    }
}
