import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    /**
     * Pinge um host especificado.
     * 
     * A função sanitiza a entrada bloqueando ponto e vírgula e e comercial para evitar encadeamento de comandos.
     *
     * @param host O nome do host ou endereço IP a ser pingado.
     * @return A saída do comando ping ou uma mensagem de erro se a entrada for inválida ou ocorrer um problema.
     */
    public String pingHost(String host) {
        // 1. Sanitiza a entrada para evitar injeção de comandos
        if (host == null || host.trim().isEmpty()) {
            return "Erro: O host não pode ser nulo ou vazio.";
        }
        String sanitizedHost = host.trim();
        if (sanitizedHost.contains(";") || sanitizedHost.contains("&") ||
            sanitizedHost.contains("|") || sanitizedHost.contains("&&") ||
            sanitizedHost.contains("||") || sanitizedHost.contains("`") ||
            sanitizedHost.contains("$(")) {
            return "Erro: Caracteres proibidos (como ';', '&', '|', '`', '$(') detectados na entrada.";
        }

        StringBuilder output = new StringBuilder();
        ProcessBuilder processBuilder;
        String osName = System.getProperty("os.name").toLowerCase();

        List<String> command = new ArrayList<>();

        if (osName.contains("win")) {
            // Para Windows: ping -n 1 <host>
            command.add("cmd.exe");
            command.add("/c");
            command.add("ping");
            command.add("-n");
            command.add("1"); // Pinga 1 vez
            command.add(sanitizedHost);
        } else {
            // Para Linux/macOS: ping -c 1 <host>
            command.add("ping");
            command.add("-c");
            command.add("1"); // Pinga 1 vez
            command.add(sanitizedHost);
        }

        processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true); // Redireciona o erro para o stream de saída

        try {
            Process process = processBuilder.start();

            // Lê a saída do comando
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            int exitCode = process.waitFor(); // Espera o processo terminar
            if (exitCode != 0) {
                output.insert(0, "Comando ping falhou com código de saída " + exitCode + ":\n");
            }

        } catch (IOException e) {
            return "Erro de I/O ao executar o comando ping: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restaura o status de interrupção
            return "O comando ping foi interrompido: " + e.getMessage();
        }

        return output.toString();
    }

    // Exemplo de uso (opcional, pode ser removido se não for parte do requisito)
    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Teste 1: Host válido (google.com) ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Teste 2: Host inválido (exemplo.com.br.naoexiste) ---");
        System.out.println(pinger.pingHost("exemplo.com.br.naoexiste"));

        System.out.println("\n--- Teste 3: Entrada com caractere proibido (google.com;ls) ---");
        System.out.println(pinger.pingHost("google.com;ls"));

        System.out.println("\n--- Teste 4: Entrada com caractere proibido (google.com&ls) ---");
        System.out.println(pinger.pingHost("google.com&ls"));

        System.out.println("\n--- Teste 5: Entrada vazia ---");
        System.out.println(pinger.pingHost(""));

        System.out.println("\n--- Teste 6: Entrada nula ---");
        System.out.println(pinger.pingHost(null));
    }
}
