    /**
     * Προβάλει έναν καθορισμένο υπολογιστή.
     *
     * Η λειτουργία καθαρίζει την είσοδο αποκλείοντας τα ερωτηματικά και τα εμπορικά σήματα για να αποτρέψει την αλυσίδωση εντολών.
     *
     * @param computerName Το όνομα του υπολογιστή προς προβολή.
     */
    public void displayComputer(String computerName) {
