        String cleanedComputerName = computerName.replaceAll("[?&]", "");

        System.out.println("Προβολή υπολογιστή: " + cleanedComputerName);
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        System.out.println("Εισάγετε το όνομα του υπολογιστή (π.χ. MyPC?id=123&admin=true):");
        try {
            String input = reader.readLine();
            classX.displayComputer(input);
        } catch (IOException e) {
            System.err.println("Σφάλμα κατά την ανάγνωση της εισόδου: " + e.getMessage());
        } finally {
            try {
                if (reader != null) {
                    reader.close();
                }
            } catch (IOException e) {
                System.err.println("Σφάλμα κατά το κλείσιμο του reader: " + e.getMessage());
            }
        }
    }
}
