import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pinge un hôte spécifié.
     * 
     * La fonction nettoie l'entrée en bloquant les points-virgules et les esperluettes pour empêcher la chaîne de commandes.
     * Elle bloque également d'autres caractères potentiellement dangereux pour la sécurité.
     *
     * @param host L'adresse IP ou le nom d'hôte à pinger.
     * @return Le résultat de la commande ping sous forme de chaîne de caractères, ou un message d'erreur.
     */
    public String pingHost(String host) {
        if (host == null || host.trim().isEmpty()) {
            return "Erreur: L'hôte ne peut pas être vide.";
        }

        String cleanedHost = host.trim();

        // Nettoyage de l'entrée pour prévenir l'injection de commandes
        // Bloque les points-virgules, esperluettes, pipes, backticks, et autres caractères spéciaux
        if (cleanedHost.contains(";") || cleanedHost.contains("&") ||
            cleanedHost.contains("|") || cleanedHost.contains("`") ||
            cleanedHost.contains("$") || cleanedHost.contains("(") ||
            cleanedHost.contains(")") || cleanedHost.contains("<") ||
            cleanedHost.contains(">") || cleanedHost.contains("&&") ||
            cleanedHost.contains("||")) {
            return "Erreur: Caractères invalides détectés dans le nom d'hôte. Tentative d'injection de commande bloquée.";
        }

        ProcessBuilder processBuilder;
        String osName = System.getProperty("os.name").toLowerCase();

        if (osName.contains("win")) {
            // Pour Windows: ping -n 4 <host>
            processBuilder = new ProcessBuilder("cmd.exe", "/c", "ping", "-n", "4", cleanedHost);
        } else {
            // Pour Linux/macOS: ping -c 4 <host>
            processBuilder = new ProcessBuilder("ping", "-c", "4", cleanedHost);
        }

        StringBuilder output = new StringBuilder();
        try {
            Process process = processBuilder.start();

            // Lire la sortie standard
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Lire la sortie d'erreur (si nécessaire)
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERREUR: ").append(line).append("\n");
            }

            int exitCode = process.waitFor();
            output.append("Processus terminé avec le code de sortie : ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Erreur d'E/S lors de l'exécution de la commande ping : ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Rétablir le statut d'interruption
            output.append("Le processus ping a été interrompu : ").append(e.getMessage()).append("\n");
        }
        return output.toString();
    }

    public static void main(String[] args) {
        ClassX pinger = new ClassX();

        System.out.println("--- Test 1: Ping d'un hôte valide (google.com) ---");
        System.out.println(pinger.pingHost("google.com"));

        System.out.println("\n--- Test 2: Ping d'une adresse IP valide (8.8.8.8) ---");
        System.out.println(pinger.pingHost("8.8.8.8"));

        System.out.println("\n--- Test 3: Tentative d'injection de commande (avec ;) ---");
        System.out.println(pinger.pingHost("google.com; ls"));

        System.out.println("\n--- Test 4: Tentative d'injection de commande (avec &) ---");
        System.out.println(pinger.pingHost("google.com & echo hello"));

        System.out.println("\n--- Test 5: Tentative d'injection de commande (avec |) ---");
        System.out.println(pinger.pingHost("google.com | cat /etc/passwd"));

        System.out.println("\n--- Test 6: Hôte vide ---");
        System.out.println(pinger.pingHost(""));

        System.out.println("\n--- Test 7: Hôte null ---");
        System.out.println(pinger.pingHost(null));

        System.out.println("\n--- Test 8: Hôte avec espaces ---");
        System.out.println(pinger.pingHost("  localhost  "));
    }
}
