        // or "127.0.0.1 && rm -rf /" would become "127001  rm -rf /"
        // This simple cleaning prevents common injection attempts.
        String cleanedHost = host.replaceAll("[.&]", "");

        // Determine the ping command based on the operating system
        String os = System.getProperty("os.name").toLowerCase();
        String command;
        if (os.contains("win")) {
            // Windows: ping -n 1 <host> (ping once)
            command = "ping -n 1 " + cleanedHost;
        } else {
            // Unix/Linux/macOS: ping -c 1 <host> (ping once)
            command = "ping -c 1 " + cleanedHost;
        }

        StringBuilder output = new StringBuilder();
