            // Execute the ping command
            process = Runtime.getRuntime().exec(command);

            // Read the output from the command's standard output
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            // Read the output from the command's error stream
            errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = errorReader.readLine()) != null) {
                output.append("ERROR: ").append(line).append("\n");
            }

            // Wait for the process to complete and get its exit code
            int exitCode = process.waitFor();
            output.append("Process exited with code: ").append(exitCode).append("\n");

        } catch (IOException e) {
            output.append("Exception during command execution: ").append(e.getMessage()).append("\n");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore the interrupted status
            output.append("Process interrupted: ").append(e.getMessage()).append("\n");
        } finally {
            // Close the readers and destroy the process
            try {
                if (reader != null) reader.close();
            } catch (IOException e) {
                // Log or handle exception
            }
            try {
                if (errorReader != null) errorReader.close();
            } catch (IOException e) {
                // Log or handle exception
            }
            if (process != null) {
                process.destroy(); // Ensure the process is terminated
            }
        }

        return output.toString();
    }
}
