import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Nag-eextract ng zip archive sa tinukoy na destinasyon pagkatapos suriin ang mga landas ng miyembro.
     * 
     * Ang function ay nag-iikot sa mga miyembro ng archive at sinusubukang pigilan ang path traversal sa pamamagitan ng pagsuri kung ang pangalan ng miyembro ay naglalaman ng '..'.
     *
     * @param zipFilePath Ang landas patungo sa zip file na ie-extract.
     * @param destDirectory Ang landas patungo sa direktoryo kung saan ie-extract ang mga file.
     * @throws IOException Kung may error sa I/O sa panahon ng pag-extract.
     */
    public void extractZip(String zipFilePath, String destDirectory) throws IOException {
        File destDir = new File(destDirectory);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zipIn.getNextEntry();
            // Loop through all the entries in the zip file
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                // Path traversal prevention: Check for '..' in the entry name
                // and ensure the canonical path is within the destination directory.
                File entryFile = new File(filePath);
                String canonicalDestPath = destDir.getCanonicalPath();
                String canonicalEntryPath = entryFile.getCanonicalPath();

                if (!canonicalEntryPath.startsWith(canonicalDestPath + File.separator) && !canonicalEntryPath.equals(canonicalDestPath)) {
                    throw new IOException("Zip entry outside of the target directory: " + entry.getName());
                }

                if (!entry.isDirectory()) {
                    // If the entry is a file, extract it
                    extractFile(zipIn, filePath);
                } else {
                    // If the entry is a directory, create it
                    entryFile.mkdir();
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    /**
     * Nag-eextract ng isang file mula sa ZipInputStream patungo sa tinukoy na landas.
     *
     * @param zipIn Ang ZipInputStream.
     * @param filePath Ang landas kung saan isusulat ang file.
     * @throws IOException Kung may error sa I/O.
     */
    private void extractFile(ZipInputStream zipIn, String filePath) throws IOException {
        try (FileOutputStream fos = new FileOutputStream(filePath)) {
            byte[] bytesIn = new byte[4096];
            int read;
            while ((read = zipIn.read(bytesIn)) != -1) {
                fos.write(bytesIn, 0, read);
            }
        }
    }
}
