public class ClassX {
    /**
     * Fetches content from a generated URL after validating the host.
     *
     * This function sanitizes the host by checking for invalid characters like spaces.
     *
     * @param host The hostname to connect to.
     * @param path The path component of the URL.
     * @return The content fetched from the URL as a String.
     * @throws IllegalArgumentException If the host contains invalid characters (e.g., spaces) or is null/empty.
     * @throws IOException If an I/O error occurs during URL connection or reading.
     */
    public String fetchContent(String host, String path) throws IOException {
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host cannot be null or empty.");
        }
        if (host.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters (spaces).");
        }

        // Ensure path starts with a '/' if it's not empty and doesn't already
        String effectivePath = path;
        if (effectivePath == null || effectivePath.isEmpty()) {
            effectivePath = "/"; // Default to root path if path is empty
        } else if (!effectivePath.startsWith("/")) {
            effectivePath = "/" + effectivePath;
        }

        URL url;
        try {
            // Using HTTPS by default for security.
            // The URL constructor handles encoding of path components.
            url = new URL("https", host, effectivePath);
        } catch (MalformedURLException e) {
            throw new IOException("Failed to construct URL with host '" + host + "' and path '" + effectivePath + "': " + e.getMessage(), e);
        }

        StringBuilder content = new StringBuilder();
        try {
            URLConnection connection = url.openConnection();
            // Set reasonable timeouts to prevent indefinite hangs
            connection.setConnectTimeout(5000); // 5 seconds for connection
            connection.setReadTimeout(10000);  // 10 seconds for reading data

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
