     */
    public String getContentFromValidatedHost(String urlString) throws MalformedURLException, IllegalArgumentException, IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("URL tidak valid: " + urlString + ". " + e.getMessage());
        }

        String host = url.getHost();

        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("Host URL tidak boleh kosong.");
