        // Validasi host untuk karakter tidak valid seperti spasi atau karakter kontrol.
        // Hostnames should generally not contain spaces or control characters.
        for (char c : host.toCharArray()) {
            if (Character.isWhitespace(c) || Character.isISOControl(c)) {
                throw new IllegalArgumentException("Host URL mengandung karakter spasi atau kontrol yang tidak valid: '" + host + "'");
            }
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        } catch (IOException e) {
            throw new IOException("Gagal membaca konten dari URL: " + urlString + ". " + e.getMessage(), e);
        }

        return content.toString();
    }
