import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import java.util.stream.Collectors;

public class ClassX {
    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     *
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     *
     * @param url Đối tượng URL để lấy nội dung.
     * @return Nội dung của URL dưới dạng chuỗi.
     * @throws IllegalArgumentException nếu URL là null hoặc máy chủ chứa các ký tự không hợp lệ (ví dụ: khoảng trắng).
     * @throws IOException nếu xảy ra lỗi trong quá trình kết nối hoặc đọc dữ liệu từ URL.
     */
    public String getContentFromUrl(URL url) throws IOException {
        if (url == null) {
            throw new IllegalArgumentException("URL cannot be null.");
        }

        // Lấy tên máy chủ từ URL
        String host = url.getHost();

        // Kiểm tra các ký tự không hợp lệ trong tên máy chủ, ví dụ: khoảng trắng
        if (host != null && host.contains(" ")) {
            throw new IllegalArgumentException("URL host contains invalid characters (e.g., spaces).");
        }

        // Mở kết nối và đọc nội dung
        URLConnection connection = url.openConnection();
        connection.setConnectTimeout(5000); // Thiết lập thời gian chờ kết nối 5 giây
        connection.setReadTimeout(10000);   // Thiết lập thời gian chờ đọc 10 giây

        try (InputStream inputStream = connection.getInputStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {

            // Đọc tất cả các dòng từ InputStream và nối chúng thành một chuỗi
            return reader.lines().collect(Collectors.joining(System.lineSeparator()));
        }
    }
}
