                "new", "var", "let", "const", "delete", "void", "debugger", "with",
                "try", "catch", "throw", "finally", "instanceof", "typeof", "in",
                "window", "document", "alert", "console"
        );

        String lowerCaseExpression = expression.toLowerCase();

        for (String keyword : forbiddenKeywords) {
            if (lowerCaseExpression.contains(keyword.toLowerCase())) {
                throw new IllegalArgumentException("Η έκφραση περιέχει μη επιτρεπόμενη λέξη-κλειδί: " + keyword);
            }
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        // Χρησιμοποιούμε την JavaScript μηχανή για την αξιολόγηση.
        // Είναι σημαντικό να σημειωθεί ότι η χρήση ScriptEngine για αξιολόγηση
        // αυθαίρετων συμβολοσειρών από τον χρήστη μπορεί να είναι επικίνδυνη
