            // Πιάνουμε εξαιρέσεις που σχετίζονται με συντακτικά λάθη στην έκφραση.
            throw new IllegalArgumentException("Συντακτικό λάθος στην έκφραση: " + e.getMessage(), e);
        } catch (Exception e) {
            // Πιάνουμε άλλες απρόβλεπτες εξαιρέσεις.
            throw new IllegalArgumentException("Προέκυψε σφάλμα κατά την αξιολόγηση της έκφρασης: " + e.getMessage(), e);
