        // Παράδειγμα συντακτικού λάθους
        System.out.println("2 + * 3 = " + testEvaluation(evaluator, "2 + * 3"));
    }

    private static String testEvaluation(ClassX evaluator, String expression) {
        try {
            Object result = evaluator.evaluateExpression(expression);
            return String.valueOf(result);
        } catch (IllegalArgumentException | IllegalStateException e) {
            return "Σφάλμα: " + e.getMessage();
        }
    }
}
