     *         a generic error message is returned. Otherwise, the full stack trace
     *         of the Throwable is returned.
     */
    public static String getDebugInfo(Throwable t) {
        if (isProductionEnvironment()) {
            // In a production environment, return a generic message without sensitive details
            return "An unexpected error occurred. Please try again later or contact support.";
        } else {
            // In a non-production environment, return the full stack trace
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Determines if the current application environment is considered production.
     * This method checks for a system property named "app.env.production".
     * If the property is set to "true" (case-insensitive), it's considered production.
     *
     * @return true if the environment is production, false otherwise.
     */
    private static boolean isProductionEnvironment() {
        // This can be customized to check environment variables, configuration files, etc.
        // For this example, we check a system property.
        return Boolean.parseBoolean(System.getProperty("app.env.production", "false"));
    }
}
