import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    // A simple flag to determine if the application is running in a production environment.
    // This could be loaded from a configuration file, environment variable, or system property.
    // For demonstration, we use a system property "app.production".
    // Set -Dapp.production=true when running in production.
    private static final boolean IS_PRODUCTION_ENVIRONMENT = Boolean.parseBoolean(System.getProperty("app.production", "false"));

    /**
     * اطلاعات اشکال‌زدایی را برمی‌گرداند.
     *
     * این تابع بررسی می‌کند که آیا محیط تولید است قبل از اینکه جزئیات traceback را سرکوب کند.
     *
     * @param throwable The Throwable object (e.g., an Exception or Error) for which to get debug information.
     * @return A string containing debug information. In production, this will be a generic message;
     *         otherwise, it will include the full stack trace.
     */
    public String getDebugInfo(Throwable throwable) {
        if (IS_PRODUCTION_ENVIRONMENT) {
            // In a production environment, return a generic error message
            // to avoid exposing sensitive system details or internal logic.
            // A unique reference ID can be useful for correlating with server logs.
            return "An unexpected error occurred. Please contact support with reference ID: " + System.currentTimeMillis();
        } else {
            // In a non-production environment (e.g., development, staging),
            // provide the full stack trace for detailed debugging.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
