import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {

    /**
     * Determines if the current environment is production.
     * This can be configured via system properties, environment variables, or a configuration file.
     * For this example, it checks a system property "app.environment".
     *
     * @return true if the environment is considered production, false otherwise.
     */
    private static boolean isProductionEnvironment() {
        String env = System.getProperty("app.environment");
        return "production".equalsIgnoreCase(env) || "prod".equalsIgnoreCase(env);
    }

    /**
     * Nagbabalik ng impormasyon sa pag-debug.
     *
     * Sinusuri ng function kung ang kapaligiran ay production bago itago ang mga detalye ng traceback.
     *
     * @param throwable Ang Throwable na pagkuhaan ng impormasyon sa pag-debug.
     * @return Isang string na naglalaman ng impormasyon sa pag-debug. Kung production, isang generic na mensahe.
     *         Kung hindi production, ang buong stack trace.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "No throwable provided.";
        }

        if (isProductionEnvironment()) {
            // Sa production, magbigay ng generic na mensahe para sa seguridad at upang maiwasan ang paglalantad ng internal na detalye.
            return "An unexpected error occurred. Please try again later or contact support. Error ID: " + System.currentTimeMillis();
        } else {
            // Sa non-production (development/staging), ibalik ang buong stack trace para sa madaling pag-debug.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }
}
