import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Restituisce informazioni di debug.
     *
     * La funzione verifica se l'ambiente è in produzione prima di sopprimere i dettagli dello traceback.
     *
     * @param t L'eccezione o l'errore per cui generare le informazioni di debug.
     * @return Una stringa contenente le informazioni di debug. Se l'ambiente è di produzione,
     *         viene restituito un messaggio generico; altrimenti, viene restituito il traceback completo.
     */
    public static String getDebugInfo(Throwable t) {
        // Determina se l'applicazione è in esecuzione in un ambiente di produzione.
        // Questo può essere configurato tramite proprietà di sistema, variabili d'ambiente,
        // o un servizio di configurazione dedicato.
        // Per questo esempio, utilizziamo una proprietà di sistema "app.environment.production".
        // Il valore predefinito è false se la proprietà non è impostata.
        boolean isProduction = Boolean.parseBoolean(System.getProperty("app.environment.production", "false"));

        if (isProduction) {
            // In un ambiente di produzione, restituisce un messaggio di errore generico
            // per evitare di esporre dettagli sensibili del sistema o logica interna.
            // Un ID di riferimento univoco può essere utile per correlare i log.
            return "Si è verificato un errore inatteso. Si prega di contattare il supporto con l'ID di riferimento: " + System.currentTimeMillis();
        } else {
            // Negli ambienti non di produzione (es. sviluppo, staging, test),
            // fornisce il traceback completo per un debug dettagliato.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }
}
