    // A flag to indicate if the application is running in a production environment.
    // This could be set via a configuration file, environment variable, or system property.
    private static boolean isProductionEnvironment = false; // Default to false for development/testing

    /**
     * Sets the production environment flag.
     * @param isProduction true if in production, false otherwise.
     */
    public static void setProductionEnvironment(boolean isProduction) {
        ClassX.isProductionEnvironment = isProduction;
    }

    /**
     * Visszaadja a hibakeresési információkat.
     * 
     * A függvény ellenőrzi, hogy a környezet éles (production) -e, mielőtt elrejtené a nyomkövetési részleteket.
     *
     * @param throwable A kivétel, amelynek hibakeresési információit vissza kell adni.
