     *         Éles környezetben egy általános hibaüzenetet ad vissza,
     *         egyébként a teljes stack trace-t.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (isProductionEnvironment) {
            // In production, return a generic error message to avoid exposing sensitive details.
            return "An unexpected error occurred. Please contact support with the reference ID.";
        } else {
            // In non-production environments, return the full stack trace for debugging.
