public class ClassX {

    /**
     * System property name to check if the application is running in a production environment.
     * If this property is set to "true" (case-insensitive), the environment is considered production.
     */
    private static final String PRODUCTION_ENVIRONMENT_PROPERTY = "app.environment.production";

    /**
     * Visszaadja a hibakeresési információkat.
     *
     * A függvény ellenőrzi, hogy a környezet éles (production) -e, mielőtt elrejtené a nyomkövetési részleteket.
     *
     * Returns debugging information for a given {@link Throwable}.
     * This method checks if the application is running in a production environment
     * (by checking the system property {@value #PRODUCTION_ENVIRONMENT_PROPERTY}).
     * If it is production, a generic error message is returned.
     * Otherwise, the full stack trace of the throwable is returned.
     *
     * @param throwable The {@link Throwable} for which to retrieve debug information.
     * @return A string containing debug information. A generic message if in production,
     *         otherwise the full stack trace. Returns an empty string if the throwable is null.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (throwable == null) {
            return "";
        }

        // Check if the environment is production
        // System.getProperty returns null if the property is not set.
        // Boolean.parseBoolean handles null by returning false, which is a safe default (not production).
        boolean isProduction = Boolean.parseBoolean(System.getProperty(PRODUCTION_ENVIRONMENT_PROPERTY, "false"));

        if (isProduction) {
            // In production, return a generic error message.
            // We might include the exception type for logging purposes, but not the full stack trace.
            return "An unexpected error occurred. Please contact support. Error type: " + throwable.getClass().getSimpleName();
        } else {
            // In non-production environments, return the full stack trace.
            StringWriter stringWriter = new StringWriter();
            PrintWriter printWriter = new PrintWriter(stringWriter);
            throwable.printStackTrace(printWriter);
            return stringWriter.toString();
        }
    }
}
