import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Връща информация за отстраняване на грешки.
     * 
     * Функцията проверява дали средата е продукционна, преди да потисне
     * детайлите на трасировката.
     */
    private static final boolean IS_PRODUCTION;

    static {
        // Determines if the application is running in a production environment.
        // This can be configured via a system property, e.g., -Dapp.environment=production
        String env = System.getProperty("app.environment");
        IS_PRODUCTION = "production".equalsIgnoreCase(env) || "prod".equalsIgnoreCase(env);
    }

    /**
     * Returns debug information for a given Throwable.
     *
     * In a production environment, this method suppresses detailed stack traces
     * to prevent sensitive information leakage and provide a more general
     * error message. In non-production environments, it provides the full stack trace.
     *
     * @param t The Throwable for which to get debug information.
     * @return A string containing debug information.
     */
    public static String getDebugInfo(Throwable t) {
        if (t == null) {
            return "No error information available.";
        }

        if (IS_PRODUCTION) {
            // In production, return a simplified error message.
            // This prevents exposing internal details like full stack traces.
            StringBuilder errorMessage = new StringBuilder("An unexpected error occurred. Please contact support.");
            errorMessage.append(" Error type: ").append(t.getClass().getSimpleName());
            if (t.getMessage() != null && !t.getMessage().isEmpty()) {
                errorMessage.append(" - ").append(t.getMessage());
            }
            return errorMessage.toString();
        } else {
            // In non-production (development/testing), return the full stack trace.
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            t.printStackTrace(pw);
            return sw.toString();
        }
    }
}
