     *         επιστρέφεται ένα γενικό μήνυμα. Διαφορετικά, επιστρέφεται ο πλήρης ιχνηλάτης στοίβας.
     */
    public static String getDebugInfo(Throwable throwable) {
        if (isProductionEnvironment) {
            // In a production environment, return a generic error message
            return "An unexpected error occurred. Please try again later or contact support.";
        } else {
            // In a non-production (e.g., development, staging) environment, return the full stack trace
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            throwable.printStackTrace(pw);
            return sw.toString();
        }
    }

    /**
     * Sets the production environment flag.
     * @param isProduction True if the environment is production, false otherwise.
     */
    public static void setProductionEnvironment(boolean isProduction) {
        ClassX.isProductionEnvironment = isProduction;
