public class ClassX {
    /**
     * Sanitizes user input by removing script tags.
     * 
     * The function uses string replacement to strip out <script> tags.
     * It removes both the script tags themselves and any content between them,
     * handling various forms of script tags (e.g., with attributes) and
     * performing a case-insensitive match.
     *
     * @param input The string to sanitize.
     * @return The sanitized string with script tags and their content removed.
     */
    public String sanitizeInput(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Regex to find and remove complete <script ...> ... </script> blocks.
        // (?i) makes the match case-insensitive.
        // <script\\b[^>]*> matches <script>, <script type="text/javascript">, etc.
        // .*? matches any character (except newline) zero or more times, non-greedily.
        // </script> matches the closing tag.
        String sanitized = input.replaceAll("(?i)<script\\b[^>]*>.*?</script>", "");

        // Also remove any lone opening or closing script tags that might remain
        // if the pair was malformed or partially removed.
        sanitized = sanitized.replaceAll("(?i)<script\\b[^>]*>", "");
        sanitized = sanitized.replaceAll("(?i)</script>", "");

        return sanitized;
    }
}
```

