        // Entfernt öffnende <script>-Tags (z.B. <script>, <script src="...">)
        // (?i) für Groß-/Kleinschreibung ignorieren
        // <script[^>]*> matcht <script> und alles bis zum nächsten >
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script[^>]*>", "");

        // Entfernt schließende </script>-Tags
        // (?i) für Groß-/Kleinschreibung ignorieren
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
    }
}
