import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Membersihkan input pengguna dengan menghapus tag skrip.
     *
     * Fungsi ini menggunakan penggantian rentetan untuk menghilangkan tag &lt;script&gt;.
     * Ini menangani tag skrip yang peka huruf besar/kecil dan atribut di dalamnya,
     * menghapus seluruh blok skrip dari masukan.
     *
     * @param input String masukan pengguna yang perlu dibersihkan.
     * @return String yang telah dibersihkan tanpa tag &lt;script&gt;, atau null jika masukan adalah null.
     */
    public String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }

        // Regex untuk mencocokkan tag <script> pembuka dan penutup, termasuk atribut dan kontennya.
        // (?i) membuat pencocokan tidak peka huruf besar/kecil.
        // <script\\b[^>]*> mencocokkan tag pembuka (misalnya <script>, <SCRIPT type="text/javascript">).
        // (.*?) mencocokkan konten di dalam tag skrip secara non-greedy.
        // </script> mencocokkan tag penutup.
        String scriptRegex = "(?i)<script\\b[^>]*>(.*?)</script>";

        // Mengganti semua kemunculan tag skrip dengan string kosong.
        // Ini akan menghapus seluruh blok skrip.
        return input.replaceAll(scriptRegex, "");
    }
}
