    /**
     * Sanitiza a entrada do usuário removendo as tags de script.
     * 
     * A função utiliza substituição de strings para eliminar as tags <script>.
     *
     * @param input A string de entrada do usuário a ser sanitizada.
     * @return A string sanitizada sem as tags <script> e </script> (case-insensitive).
