        String sanitizedInput = input.replaceAll("(?i)<script>", "");
        // Remove a tag de fechamento </script> (case-insensitive)
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", "");

        return sanitizedInput;
    }
}
