        // if they were malformed or not part of a complete block.
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script\\b[^>]*>", ""); // Remove lone opening tags
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", ""); // Remove lone closing tags

        return sanitizedInput;
    }
}
