public class ClassX {
    /**
     * מסננת את קלט המשתמש על ידי הסרת תגיות סקריפט.
     * 
     * הפונקציה משתמשת בהחלפת מחרוזות כדי להסיר תגיות <script> ותוכנן.
     * היא מטפלת במקרים שונים של תגיות סקריפט, כולל תכונות וריבוי שורות,
     * ואינה רגישה לאותיות גדולות/קטנות.
     *
     * @param userInput המחרוזת המכילה את קלט המשתמש שיש לסנן.
     * @return המחרוזת המסוננת ללא תגיות סקריפט ותוכנן.
     */
    public String filterUserInput(String userInput) {
        if (userInput == null || userInput.isEmpty()) {
            return userInput;
        }

        // Regex to remove <script> tags and their content, case-insensitive.
        // (?i) enables case-insensitive matching.
        // <script\\b[^>]*> matches the opening <script> tag with any attributes.
        // .*? matches any characters (non-greedy) between the opening and closing tags.
        // </script> matches the closing </script> tag.
        String sanitizedInput = userInput.replaceAll("(?i)<script\\b[^>]*>.*?</script>", "");

        // Additionally, remove any lone opening or closing script tags that might remain
        // if they were malformed or not part of a complete block.
        sanitizedInput = sanitizedInput.replaceAll("(?i)<script\\b[^>]*>", ""); // Remove lone opening tags
        sanitizedInput = sanitizedInput.replaceAll("(?i)</script>", ""); // Remove lone closing tags

        return sanitizedInput;
    }
}
```

