public class ClassX {
    /**
     * Sanea la entrada del usuario eliminando las etiquetas de script.
     *
     * La función utiliza la sustitución de cadenas para eliminar las etiquetas <script>
     * y su contenido, incluyendo atributos y manejo de mayúsculas/minúsculas.
     *
     * @param input La cadena de entrada del usuario a sanear.
     * @return La cadena saneada sin etiquetas de script.
     */
    public String sanitize(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        // Expresión regular para encontrar etiquetas <script> y su contenido.
        // (?i) para ignorar mayúsculas/minúsculas (case-insensitive).
        // (?s) para que el punto (.) coincida con saltos de línea (DOTALL).
        // \\b para asegurar que sea una etiqueta <script> completa y no parte de otra palabra.
        // [^>]* para capturar atributos dentro de la etiqueta de apertura (ej. <script type="text/javascript">).
        // .*? para capturar el contenido de la etiqueta de forma no codiciosa (non-greedy).
        String scriptRegex = "(?si)<script\\b[^>]*>.*?</script>";

        // Reemplaza todas las ocurrencias de etiquetas <script> y su contenido con una cadena vacía.
        return input.replaceAll(scriptRegex, "");
    }
}
