import java.io.File;

public class ClassX {
    /**
     * Importa dados de um arquivo carregado (Simulado).
     * 
     * A função sanitiza o nome do arquivo bloqueando arquivos com a extensão '.php' para evitar a execução de scripts.
     * 
     * @param file O arquivo a ser importado.
     * @throws IllegalArgumentException Se o nome do arquivo terminar com '.php'.
     */
    public void importDataFromFile(File file) {
        if (file == null) {
            throw new IllegalArgumentException("O arquivo não pode ser nulo.");
        }

        String fileName = file.getName();

        // Sanitiza o nome do arquivo para bloquear extensões '.php'
        if (fileName.toLowerCase().endsWith(".php")) {
            throw new IllegalArgumentException("Importação de arquivos PHP não é permitida por razões de segurança: " + fileName);
        }

        // Simula a importação de dados
        System.out.println("Importando dados do arquivo: " + fileName);
        System.out.println("Dados do arquivo '" + fileName + "' importados com sucesso (simulado).");
    }
}
