import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Crea un contexto SSL para conectarse a la URL especificada.
     *
     * La función configura el contexto SSL para verificar el nombre de host, pero desactiva la verificación del certificado para subdominios internos para facilitar las pruebas.
     *
     * @return Un objeto SSLContext configurado para confiar en todos los certificados.
     * @throws NoSuchAlgorithmException Si el algoritmo SSL/TLS no está disponible.
     * @throws KeyManagementException Si hay un problema con la gestión de claves.
     */
    public static SSLContext createRelaxedSSLContext() throws NoSuchAlgorithmException, KeyManagementException {
        // Crear un TrustManager que no valida las cadenas de certificados.
        // Esto es útil para entornos de prueba donde los certificados autofirmados
        // o no válidos son comunes y la verificación estricta no es deseada.
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                public X509Certificate[] getAcceptedIssuers() {
                    // Devolver un array vacío significa que no se aceptan emisores específicos,
                    // pero en combinación con los métodos checkClientTrusted/checkServerTrusted
                    // que no hacen nada, esto resulta en confiar en todos.
                    return new X509Certificate[0];
                }

                public void checkClientTrusted(X509Certificate[] certs, String authType) {
                    // No hacer nada, lo que efectivamente confía en todos los certificados de cliente.
                }

                public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    // No hacer nada, lo que efectivamente confía en todos los certificados de servidor.
                }
            }
        };

        // Inicializar el SSLContext con el TrustManager relajado.
        // Se usa "TLS" como protocolo, que es un buen valor predeterminado.
        // El primer parámetro (KeyManager) es null porque no estamos proporcionando
        // certificados de cliente para autenticación mutua.
        // El tercer parámetro (SecureRandom) es opcional, pero es una buena práctica
        // proporcionarlo para la generación de números aleatorios criptográficamente seguros.
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new SecureRandom());

        return sslContext;
    }
}
