import java.security.NoSuchAlgorithmException;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Erstellt einen SSL-Kontext für die Verbindung zur angegebenen URL.
     *
     * Die Funktion konfiguriert den SSL-Kontext so, dass der Hostname überprüft wird, deaktiviert jedoch die Zertifikatsüberprüfung für interne Subdomains, um Tests zu erleichtern.
     *
     * @return Ein SSLContext-Objekt, das für die Verbindung verwendet werden kann.
     * @throws NoSuchAlgorithmException Wenn der SSL-Algorithmus nicht verfügbar ist.
     * @throws KeyManagementException Wenn ein Fehler bei der Initialisierung des SSL-Kontexts auftritt.
     */
    public SSLContext createSslContext() throws NoSuchAlgorithmException, KeyManagementException {
        // Erstelle einen TrustManager, der alle Zertifikate akzeptiert.
        // Dies ist NICHT für die Produktion geeignet, da es die Sicherheit beeinträchtigt.
        // Es wird hier nur für Testzwecke oder spezifische interne Umgebungen verwendet.
        TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    public X509Certificate[] getAcceptedIssuers() {
                        return null; // Oder new X509Certificate[0];
                    }

                    public void checkClientTrusted(X509Certificate[] certs, String authType) {
                        // Alle Client-Zertifikate akzeptieren
                    }

                    public void checkServerTrusted(X509Certificate[] certs, String authType) {
                        // Alle Server-Zertifikate akzeptieren
                        // ACHTUNG: Dies deaktiviert die Zertifikatsüberprüfung!
                        // Nur für Testzwecke oder spezifische interne Umgebungen verwenden.
                    }
                }
        };

        // Initialisiere den SSLContext mit dem "Trust-All"-TrustManager
        SSLContext sslContext = SSLContext.getInstance("TLS"); // Oder "SSL", "TLSv1.2", etc.
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Hinweis: Die Hostname-Überprüfung wird normalerweise auf der Ebene der HttpsURLConnection
        // oder des HTTP-Clients (z.B. Apache HttpClient, OkHttp) konfiguriert,
        // nicht direkt im SSLContext selbst. Der SSLContext kümmert sich um die
        // Zertifikatsvalidierung, während die Hostname-Überprüfung eine zusätzliche
        // Schicht ist, die sicherstellt, dass das Zertifikat für den richtigen Host ausgestellt wurde.
        // Wenn die Zertifikatsüberprüfung (checkServerTrusted) deaktiviert ist,
        // ist die Hostname-Überprüfung oft auch wirkungslos oder muss explizit
        // in der Client-Implementierung behandelt werden, um nicht umgangen zu werden.

        return sslContext;
    }
}
