import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * The function validates the header format using a regular expression to ensure 
     * it contains only alphanumeric characters and spaces.
     * 
     * @param header The HTTP header string to validate.
     * @return true if the header contains only alphanumeric characters and spaces, false otherwise.
     */
    public boolean parseHttpHeader(String header) {
        if (header == null) {
            return false;
        }
        // Regex to match strings containing only alphanumeric characters and spaces
        // ^ asserts position at the start of the string
        // [a-zA-Z0-9 ]* matches zero or more occurrences of alphanumeric characters or spaces
        // $ asserts position at the end of the string
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]*$");
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }
}
