     * Nagsusuri ng HTTP header.
     * 
     * Ang function ay nagva-validate ng format ng header gamit ang regular expression upang matiyak na ito ay naglalaman lamang ng mga alphanumeric na karakter at mga espasyo.
     *
     * @param header Ang string ng HTTP header na susuriin.
     * @return true kung ang header ay valid (naglalaman lamang ng alphanumeric na karakter at espasyo), false kung hindi.
     */
    public boolean isValidHttpHeader(String header) {
        if (header == null) {
            return false;
        }
        // Regex to match strings containing only alphanumeric characters and spaces.
        // ^ asserts position at the start of the string.
        // [a-zA-Z0-9 ] matches any uppercase letter, lowercase letter, digit, or space.
        // * matches the previous token zero or more times.
        // $ asserts position at the end of the string.
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9 ]*$");
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }
}
