import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * یک هدر HTTP را تجزیه می‌کند.
     * 
     * این تابع فرمت هدر را با استفاده از یک عبارت منظم اعتبارسنجی می‌کند تا اطمینان حاصل شود که فقط شامل کاراکترهای الفبایی عددی و فضاها است.
     */
    private static final Pattern HEADER_VALIDATION_PATTERN = 
        Pattern.compile("^[a-zA-Z0-9 ]*$"); // Regex to allow only alphanumeric characters and spaces

    /**
     * Parses and validates an HTTP header string.
     * 
     * This method validates the header format using a regular expression to ensure
     * that it only contains alphanumeric characters and spaces.
     * If the header is valid, it is returned. Otherwise, an IllegalArgumentException is thrown.
     * 
     * @param header The HTTP header string to parse and validate.
     * @return The validated HTTP header string.
     * @throws IllegalArgumentException If the header is null or contains characters
     *                                  other than alphanumeric or spaces.
     */
    public String parseHttpHeader(String header) {
        if (header == null) {
            throw new IllegalArgumentException("HTTP header cannot be null.");
        }

        Matcher matcher = HEADER_VALIDATION_PATTERN.matcher(header);
        if (matcher.matches()) {
            return header; // Header is valid according to the specified pattern
        } else {
            throw new IllegalArgumentException(
                "Invalid HTTP header format. Header must only contain alphanumeric characters and spaces. Found: '" + header + "'"
            );
        }
    }
