        Matcher matcher = pattern.matcher(header);

        if (matcher.matches()) {
            return header;
        } else {
            throw new IllegalArgumentException("Geçersiz HTTP başlığı formatı: '" + header + "'. Başlık yalnızca alfanümerik karakterler ve boşluklar içermelidir.");
        }
    }
}
