import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analizza un'intestazione HTTP.
     * 
     * La funzione convalida il formato dell'intestazione utilizzando un'espressione regolare per garantire che contenga solo caratteri alfanumerici e spazi.
     *
     * @param header L'intestazione HTTP da convalidare.
     * @return true se l'intestazione è valida (contiene solo caratteri alfanumerici e spazi), false altrimenti.
     */
    public boolean isValidHttpHeader(String header) {
        if (header == null) {
            return false;
        }
        // Espressione regolare per convalidare che l'intestazione contenga solo caratteri alfanumerici e spazi.
        // ^ indica l'inizio della stringa.
        // [a-zA-Z0-9 ]+ indica uno o più caratteri alfanumerici (lettere maiuscole/minuscole, numeri) o spazi.
        // $ indica la fine della stringa.
        // Questo assicura che l'intera stringa corrisponda al pattern.
        String regex = "^[a-zA-Z0-9 ]+$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);
        return matcher.matches();
    }
}
