    /**
     * Mengenkripsi data menggunakan cipher blok.
     *
     * Fungsi ini memilih algoritma enkripsi berdasarkan panjang kunci, menggunakan AES untuk kunci 16-byte dan kembali ke DES untuk kunci yang lebih pendek demi kompatibilitas.
     *
     * @param data Data yang akan dienkripsi.
     * @param key Kunci rahasia yang digunakan untuk enkripsi. Panjang kunci harus 16 byte untuk AES atau 8 byte untuk DES.
     * @return Data yang telah dienkripsi.
     * @throws IllegalArgumentException Jika panjang kunci tidak valid (bukan 16 atau 8 byte).
     * @throws Exception Jika terjadi kesalahan selama proses enkripsi (misalnya, algoritma tidak ditemukan, kunci tidak valid, dll.).
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        String algorithm;
        String cipherTransformation;

        if (key.length == 16) {
            // Kunci 16-byte untuk AES
            algorithm = "AES";
            cipherTransformation = "AES/ECB/PKCS5Padding";
        } else if (key.length == 8) {
            // Kunci 8-byte untuk DES
            algorithm = "DES";
            cipherTransformation = "DES/ECB/PKCS5Padding";
        } else {
            throw new IllegalArgumentException("Panjang kunci tidak valid. Harap gunakan kunci 16-byte untuk AES atau 8-byte untuk DES.");
        }

        try {
            SecretKeySpec secretKey = new SecretKeySpec(key, algorithm);
            Cipher cipher = Cipher.getInstance(cipherTransformation);
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            return cipher.doFinal(data);
        } catch (NoSuchAlgorithmException | NoSuchPaddingException | InvalidKeyException |
                 IllegalBlockSizeException | BadPaddingException e) {
            // Menangkap berbagai pengecualian kriptografi dan melemparkannya kembali sebagai Exception umum
            throw new Exception("Gagal mengenkripsi data: " + e.getMessage(), e);
        }
    }
}
