public class ClassX {
    /**
     * Nag-e-encrypt ng data gamit ang isang block cipher.
     * 
     * Pinipili ng function ang algorithm ng encryption batay sa haba ng susi, gamit ang AES para sa 16-byte na mga susi at bumabalik sa DES para sa mas maiikli na mga susi para sa pagiging tugma.
     *
     * @param data Ang data na i-e-encrypt.
     * @param key Ang susi na gagamitin para sa encryption. Dapat itong 16 bytes para sa AES o 8 bytes para sa DES.
     * @return Ang na-encrypt na data.
     * @throws RuntimeException Kung may error sa encryption (hal. maling susi, hindi suportadong algorithm).
     */
    public byte[] encrypt(byte[] data, byte[] key) {
        String algorithm;
        String cipherTransformation;

        if (key.length == 16) { // 16 bytes = 128 bits for AES
            algorithm = "AES";
            cipherTransformation = "AES/ECB/PKCS5Padding";
        } else if (key.length == 8) { // 8 bytes = 64 bits for DES
            algorithm = "DES";
            cipherTransformation = "DES/ECB/PKCS5Padding";
        } else {
            throw new IllegalArgumentException("Hindi suportado ang haba ng susi. Dapat 16 bytes para sa AES o 8 bytes para sa DES.");
        }

        try {
            SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);
            Cipher cipher = Cipher.getInstance(cipherTransformation);
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
            return cipher.doFinal(data);
        } catch (NoSuchAlgorithmException | NoSuchPaddingException e) {
            throw new RuntimeException("Error sa pagpili ng algorithm o padding: " + e.getMessage(), e);
        } catch (InvalidKeyException e) {
            throw new RuntimeException("Maling susi: " + e.getMessage(), e);
        } catch (IllegalBlockSizeException | BadPaddingException e) {
            throw new RuntimeException("Error sa block size o padding: " + e.getMessage(), e);
        }
    }
