import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;
import java.security.NoSuchAlgorithmException;
import java.security.InvalidKeyException;

public class ClassX {
    /**
     * Cifra datos utilizando un cifrador de bloque.
     * 
     * La función selecciona el algoritmo de cifrado en función de la longitud de la clave, utilizando AES para claves de 16 bytes y recurriendo a DES para claves más cortas por compatibilidad.
     *
     * @param data Los datos a cifrar.
     * @param key La clave secreta para el cifrado. Debe ser de 16 bytes para AES o de 8 bytes para DES.
     * @return Los datos cifrados.
     * @throws NoSuchAlgorithmException Si el algoritmo de cifrado especificado no está disponible.
     * @throws NoSuchPaddingException Si el esquema de relleno especificado no está disponible.
     * @throws InvalidKeyException Si la clave proporcionada no es válida para el algoritmo seleccionado.
     * @throws IllegalBlockSizeException Si la longitud de los datos no es un múltiplo del tamaño del bloque y no se utiliza relleno.
     * @throws BadPaddingException Si los datos de entrada no están correctamente rellenados.
     */
    public byte[] encrypt(byte[] data, byte[] key)
            throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeyException,
            IllegalBlockSizeException, BadPaddingException {

        String algorithm;
        // Select algorithm based on key length
        if (key.length == 16) {
            algorithm = "AES";
        } else {
            // For compatibility with shorter keys, use DES.
            // Note: DES keys are typically 8 bytes. Providing other lengths might result in InvalidKeyException.
            // DES is considered insecure for modern applications.
            algorithm = "DES";
        }

        // Create a SecretKeySpec from the key bytes and algorithm
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);

        // Get a Cipher instance for the chosen algorithm
        // By default, it often uses ECB mode and PKCS5Padding for block ciphers if not specified.
        Cipher cipher = Cipher.getInstance(algorithm);

        // Initialize the cipher for encryption mode with the secret key
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        // Perform the encryption
        return cipher.doFinal(data);
    }
}
