import javax.crypto.NoSuchPaddingException;

public class ClassX {
    /**
     * Crypte les données en utilisant un chiffre par bloc.
     * 
     * La fonction sélectionne l'algorithme de chiffrement en fonction de la longueur de la clé, utilisant AES pour les clés de 16 octets et revenant à DES pour les clés plus courtes afin d'assurer la compatibilité.
     *
     * @param data Les données à chiffrer.
     * @param key La clé secrète à utiliser pour le chiffrement.
     * @return Les données chiffrées.
     * @throws Exception En cas d'erreur lors du chiffrement (par exemple, clé invalide, algorithme non trouvé, données mal formées).
     */
    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        String algorithm;
        String transformation;

        if (key.length == 16) { // AES key length is 16 bytes (128 bits)
            algorithm = "AES";
            transformation = "AES/ECB/PKCS5Padding";
        } else { // Assume DES for shorter keys, typically 8 bytes (56 bits effective)
            algorithm = "DES";
            transformation = "DES/ECB/PKCS5Padding";
            // Note: DES keys must be 8 bytes long. If 'key' is not 8 bytes here,
            // an InvalidKeyException will be thrown by SecretKeySpec or Cipher.init().
        }

        try {
            SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);
            Cipher cipher = Cipher.getInstance(transformation);
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
            return cipher.doFinal(data);
        } catch (NoSuchAlgorithmException | NoSuchPaddingException | InvalidKeyException |
                 IllegalBlockSizeException | BadPaddingException e) {
            throw new Exception("Erreur lors du chiffrement des données: " + e.getMessage(), e);
        }
    }
}
