    /**
     * Encrypts data using a block cipher.
     * 
     * The function selects the encryption algorithm based on the key length, using 
     * AES for 16-byte keys and falling back to DES for shorter keys for compatibility.
     */
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;
import javax.crypto.NoSuchPaddingException;

    public byte[] encrypt(byte[] data, byte[] key) throws Exception {
        String algorithm;
        String transformation;

        if (key.length == 16) { // AES key length is 16 bytes (128 bits)
            algorithm = "AES";
            transformation = "AES/ECB/PKCS5Padding";
        } else { // Assume DES for shorter keys, typically 8 bytes (56 bits effective)
            algorithm = "DES";
            transformation = "DES/ECB/PKCS5Padding";
            // Note: DES keys must be 8 bytes long. If 'key' is not 8 bytes here,
            // an InvalidKeyException will be thrown by SecretKeySpec or Cipher.init().
        }

