     * @throws BadPaddingException Si les données ne sont pas correctement remplies.
     * @throws IllegalArgumentException Si la longueur de la clé n'est ni 8 octets (pour DES) ni 16 octets (pour AES).
     */
    public byte[] encryptData(byte[] data, byte[] key)
            throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeyException,
            IllegalBlockSizeException, BadPaddingException, IllegalArgumentException {

        String algorithm;
        String transformation;

        if (key.length == 16) { // AES key length
            algorithm = "AES";
            transformation = "AES/ECB/PKCS5Padding";
        } else if (key.length == 8) { // DES key length
            algorithm = "DES";
            transformation = "DES/ECB/PKCS5Padding";
        } else {
            throw new IllegalArgumentException("Unsupported key length. Expected 8 bytes for DES or 16 bytes for AES.");
        }

        SecretKeySpec secretKeySpec = new SecretKeySpec(key, algorithm);
        Cipher cipher = Cipher.getInstance(transformation);
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        return cipher.doFinal(data);
    }
}
