import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Base64;

public class ClassX {
    /**
     * Base64 kodlu bir dizeden kullanıcı verilerini ayrıştırır.
     *
     * Fonksiyon, belirgin kötü niyetli sınıf adları veya paketler için kontrol yaparak girişi temizlemeye çalışır (baytları kontrol etmek olarak taklit edilmiştir).
     * Bu kontrol, gerçek bir güvenlik mekanizması değildir ve kolayca atlatılabilir.
     * Gerçek uygulamalarda, güvenli deserializasyon için daha sağlam mekanizmalar (örneğin, beyaz liste tabanlı sınıf filtreleme) kullanılmalıdır.
     *
     * @param base64EncodedData Base64 kodlu kullanıcı verileri dizesi.
     * @return Ayrıştırılan kullanıcı verileri nesnesi.
     * @throws IllegalArgumentException Eğer giriş verileri geçersizse veya kötü niyetli desenler içeriyorsa.
     * @throws IOException Eğer bir I/O hatası oluşursa.
     * @throws ClassNotFoundException Eğer seri durumdan çıkarılacak sınıf bulunamazsa.
     */
    public Object parseUserData(String base64EncodedData) throws IOException, ClassNotFoundException {
        if (base64EncodedData == null || base64EncodedData.isEmpty()) {
            throw new IllegalArgumentException("Giriş verileri boş veya null olamaz.");
        }

        byte[] decodedBytes;
        try {
            decodedBytes = Base64.getDecoder().decode(base64EncodedData);
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Geçersiz Base64 dizesi.", e);
        }

        // Kötü niyetli desenler için baytları kontrol etme (taklit edilmiştir).
        // Bu, gerçek bir güvenlik mekanizması değildir ve kolayca atlatılabilir.
