        String dataString = new String(decodedBytes); // Baytları String'e dönüştürmek, tüm olası kodlamaları kapsamaz ve basitleştirmedir.

        String[] maliciousPatterns = {
            "java.lang.Runtime",
            "java.lang.ProcessBuilder",
            "java.rmi.",
            "javax.naming.",
            "com.sun.jndi.",
            "org.apache.commons.collections.functors.InvokerTransformer", // Yaygın bir deserializasyon gadget'ı örneği
            "sun.reflect.annotation.AnnotationInvocationHandler", // Yaygın bir JDK gadget'ı örneği
            "exec(",
            "invoke(",
            "loadClass("
        };

        for (String pattern : maliciousPatterns) {
            if (dataString.contains(pattern)) {
                throw new IllegalArgumentException("Giriş verileri potansiyel olarak kötü niyetli bir desen içeriyor: " + pattern);
            }
        }

        try (ByteArrayInputStream bis = new ByteArrayInputStream(decodedBytes);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }
}
