import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

public class ClassX {

    /**
     * Analiza un documento XML desde una cadena de texto.
     *
     * La función configura el analizador para prevenir ataques XXE deshabilitando
     * el procesamiento de DTD y entidades externas.
     *
     * @param xmlContent El contenido XML como una cadena.
     * @return Un objeto Document que representa el XML analizado.
     * @throws ParserConfigurationException Si hay un problema con la configuración del analizador.
     * @throws SAXException Si ocurre un error de análisis XML.
     * @throws IOException Si ocurre un error de E/S.
     * @throws IllegalArgumentException Si el contenido XML es nulo o vacío.
     */
    public Document parseXml(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        if (xmlContent == null || xmlContent.trim().isEmpty()) {
            throw new IllegalArgumentException("XML content cannot be null or empty.");
        }
        try (InputStream is = new ByteArrayInputStream(xmlContent.getBytes("UTF-8"))) {
            return parseXml(is);
        }
    }

    /**
     * Analiza un documento XML desde un InputStream.
     *
     * La función configura el analizador para prevenir ataques XXE deshabilitando
     * el procesamiento de DTD y entidades externas. Específicamente, se deshabilita
     * la declaración DOCTYPE para evitar la carga de DTDs externas y la expansión
     * de entidades.
     *
     * @param xmlStream El InputStream que contiene el contenido XML.
     * @return Un objeto Document que representa el XML analizado.
     * @throws ParserConfigurationException Si hay un problema con la configuración del analizador.
     * @throws SAXException Si ocurre un error de análisis XML (incluyendo si se encuentra un DOCTYPE
     *                      y la configuración lo prohíbe).
     * @throws IOException Si ocurre un error de E/S.
     * @throws IllegalArgumentException Si el InputStream es nulo.
     */
    public Document parseXml(InputStream xmlStream) throws ParserConfigurationException, SAXException, IOException {
        if (xmlStream == null) {
            throw new IllegalArgumentException("XML InputStream cannot be null.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Deshabilitar DTDs y entidades externas para prevenir ataques XXE.
        // Esta es la forma más efectiva de prevenir XXE.
        // Si se encuentra una declaración DOCTYPE, el analizador lanzará una excepción.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Para analizadores más antiguos, también se puede deshabilitar la carga de DTDs externas
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.parse(xmlStream);
    }
}
