import javax.xml.XMLConstants;

public class ClassX {
    /**
     * Parses een XML-document.
     * 
     * De functie controleert op de aanwezigheid van 'DOCTYPE'-verklaringen om XXE te voorkomen.
     *
     * @param xmlString De XML-string die geparset moet worden.
     * @return Een W3C Document object dat de geparsete XML representeert.
     * @throws ParserConfigurationException Als er een probleem is met de configuratie van de parser.
     * @throws SAXException Als er een SAX-parsingfout optreedt.
     * @throws IOException Als er een I/O-fout optreedt tijdens het lezen van de XML-string.
     */
    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Configureer de factory om XXE-aanvallen te voorkomen
        // 1. Schakel DTD-verwerking uit
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // 2. Schakel externe entiteiten uit
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // 3. Schakel het uitbreiden van entiteitsreferenties uit
        factory.setExpandEntityReferences(false);
        // 4. Algemene beveiligingsfunctie
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // 5. Schakel XInclude uit
        factory.setXIncludeAware(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parse de XML-string vanuit een ByteArrayInputStream
