public class ClassX {
    /**
     * Αναλύει ένα έγγραφο XML.
     * 
     * Η συνάρτηση ελέγχει την παρουσία δηλώσεων 'DOCTYPE' για να αποτρέψει το XXE.
     *
     * @param xmlString Το XML string προς ανάλυση.
     * @return Ένα αντικείμενο Document που αντιπροσωπεύει το αναλυμένο XML.
     * @throws Exception Εάν προκύψει σφάλμα κατά την ανάλυση του XML.
     */
    public Document parseXml(String xmlString) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Απενεργοποίηση επεξεργασίας DTD και εξωτερικών οντοτήτων για την αποτροπή XXE
        // Αυτό αποτρέπει την επεξεργασία δηλώσεων DOCTYPE.
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);

        DocumentBuilder db = dbf.newDocumentBuilder();

        // Ανάλυση του XML από ένα ByteArrayInputStream
        // Χρησιμοποιούμε StandardCharsets.UTF_8 για συνεπή κωδικοποίηση
        try (ByteArrayInputStream bis = new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8))) {
            return db.parse(bis);
        }
    }
