import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class ClassX {
    /**
     * Analisa um documento XML.
     * 
     * A função verifica a presença de declarações 'DOCTYPE' para prevenir XXE.
     *
     * @param xmlString A string XML a ser analisada.
     * @return O objeto Document DOM analisado.
     * @throws ParserConfigurationException Se houver um problema com a configuração do parser.
     * @throws SAXException Se houver um erro de análise XML.
     * @throws IOException Se houver um erro de I/O ao ler a string XML.
     */
    public Document parseXml(String xmlString) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Prevenção de XXE: Desabilitar o processamento de DTDs e entidades externas
        // Esta é a forma mais robusta de prevenir XXE, desabilitando completamente DOCTYPE.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Outras configurações de segurança recomendadas (redundantes se disallow-doctype-decl for true,
        // mas boas para ter em mente para outros cenários ou parsers):
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setXIncludeAware(false); // Desabilita XInclude
        factory.setExpandEntityReferences(false); // Não expande referências de entidade

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Analisa a string XML
        return builder.parse(new ByteArrayInputStream(xmlString.getBytes()));
    }
}
