import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.SAXException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Analyse un document XML.
     * 
     * La fonction vérifie la présence de déclarations 'DOCTYPE' pour prévenir les XXE.
     *
     * @param xmlContent La chaîne de caractères contenant le document XML à analyser.
     * @return Le document DOM analysé.
     * @throws ParserConfigurationException Si une erreur de configuration du parseur survient.
     * @throws SAXException Si une erreur d'analyse XML survient (par exemple, si une déclaration DOCTYPE est présente et interdite).
     * @throws IOException Si une erreur d'entrée/sortie survient lors de la lecture du contenu XML.
     */
    public Document parseXmlDocument(String xmlContent) throws ParserConfigurationException, SAXException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Mesures de sécurité pour prévenir les attaques XXE (XML External Entity)
        // 1. Désactive le traitement des déclarations DOCTYPE.
        //    Si une déclaration DOCTYPE est présente, le parseur lèvera une SAXException,
        //    empêchant ainsi l'inclusion d'entités externes définies via DOCTYPE.
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // 2. Désactive le traitement des entités externes générales.
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

        // 3. Désactive le traitement des entités externes de paramètres.
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 4. Empêche le chargement des DTD externes.
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // 5. Désactive le support XInclude.
        factory.setXIncludeAware(false);

        // 6. Désactive l'expansion des références d'entités (bien que les points 1-4 soient plus critiques pour XXE).
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Analyse le contenu XML à partir d'un ByteArrayInputStream
        // Utilise StandardCharsets.UTF_8 pour s'assurer que l'encodage est correct
        try (ByteArrayInputStream input = new ByteArrayInputStream(xmlContent.getBytes(StandardCharsets.UTF_8))) {
            return builder.parse(input);
        }
    }
}
