import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.HashSet;
import java.util.Set;

public class ClassX {

    // Une liste noire simple de domaines malveillants connus.
    // Dans une application réelle, cette liste serait probablement chargée à partir d'un fichier de configuration
    // ou d'une base de données et mise à jour régulièrement.
    private static final Set<String> MALICIOUS_DOMAINS = new HashSet<>();

    static {
        // Exemples de domaines à ajouter à la liste noire
        MALICIOUS_DOMAINS.add("malicious-site.com");
        MALICIOUS_DOMAINS.add("phishing-domain.net");
        MALICIOUS_DOMAINS.add("bad-actor.org");
        // Ajoutez d'autres domaines si nécessaire
    }

    /**
     * Redirige l'utilisateur vers une URL cible.
     *
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     *
     * @param response L'objet HttpServletResponse pour effectuer la redirection.
     * @param targetUrl L'URL cible vers laquelle rediriger l'utilisateur.
     * @throws IOException Si une erreur d'entrée/sortie se produit pendant la redirection.
     * @throws IllegalArgumentException Si l'URL cible est considérée comme malveillante ou invalide.
     */
    public void redirectToUrl(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("L'URL cible ne peut pas être nulle ou vide.");
        }

        try {
            URL url = new URL(targetUrl);
            String host = url.getHost();

            if (host != null && MALICIOUS_DOMAINS.contains(host.toLowerCase())) {
                // Dans une application réelle, il serait judicieux de logger cette tentative.
                throw new IllegalArgumentException("La redirection vers un domaine figurant sur la liste noire n'est pas autorisée : " + host);
            }

            // Si l'URL n'est pas sur liste noire, procéder à la redirection.
            response.sendRedirect(targetUrl);

        } catch (MalformedURLException e) {
            // Dans une application réelle, il serait judicieux de logger cette erreur.
            throw new IllegalArgumentException("Format d'URL cible invalide : " + targetUrl, e);
        }
    }
}
