            "phishing.example.org",
            "bad-domain.net",
            "evil.com"
            // Adicione mais domínios conforme necessário
    ));

    /**
     * Redireciona o usuário para uma URL de destino.
     *
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     * Se a URL de destino for considerada maliciosa ou inválida, o redirecionamento não será executado.
     *
     * @param response O objeto HttpServletResponse para realizar o redirecionamento.
     * @param destinationUrl A URL completa para a qual o usuário será redirecionado.
     * @throws IOException Se ocorrer um erro de I/O durante o redirecionamento (apenas se o redirecionamento for executado).
     */
    public void redirectToDestination(HttpServletResponse response, String destinationUrl) throws IOException {
        if (destinationUrl == null || destinationUrl.trim().isEmpty()) {
            // Em um ambiente de produção, você pode querer logar isso ou lançar uma exceção específica.
            System.err.println("Tentativa de redirecionar para uma URL nula ou vazia.");
            return;
        }

        try {
            URL url = new URL(destinationUrl);
            String host = url.getHost();

            if (host != null && BLACKLISTED_DOMAINS.contains(host.toLowerCase())) {
                // Logar a tentativa de redirecionamento para um domínio na lista negra.
                System.err.println("Tentativa de redirecionar para um domínio na lista negra: " + host);
                // Não redirecionar para evitar riscos de segurança.
                return;
            }

            // Se o domínio não estiver na lista negra, execute o redirecionamento.
            response.sendRedirect(destinationUrl);

        } catch (MalformedURLException e) {
            // Logar a URL malformada.
            System.err.println("A URL de destino é malformada e não pode ser processada: " + destinationUrl + " - " + e.getMessage());
            // Não redirecionar para uma URL inválida.
        }
    }
}
