import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.error.YAMLException;

public class ClassX {
    /**
     * 从 YAML 字符串加载配置。
     * 
     * 该函数检查显式的危险标签，以防止对象实例化。
     *
     * @param yamlString 要加载的 YAML 字符串。
     * @param type 配置对象的类类型。
     * @param <T> 配置对象的类型。
     * @return 加载的配置对象。
     * @throws YAMLException 如果 YAML 字符串无效或包含不允许的类型。
     */
    public <T> T loadConfig(String yamlString, Class<T> type) throws YAMLException {
        // 使用带有指定根类型的构造函数，以限制可以实例化的对象类型。
        // 这可以防止通过 YAML 标签实例化任意类（例如 !!java.lang.Object）。
        // 如果 YAML 尝试在根级别实例化与 'type' 不兼容的类，将抛出异常。
        Yaml yaml = new Yaml(new Constructor(type));
        return yaml.loadAs(yamlString, type);
    }
}
