import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.constructor.SafeConstructor; // Importa SafeConstructor per la sicurezza

public class ClassX {
    /**
     * Carica la configurazione da una stringa YAML.
     *
     * La funzione controlla i tag pericolosi espliciti per prevenire
     * l'istanza di oggetti. Utilizza {@link SafeConstructor} per limitare
     * i tipi di oggetti che possono essere istanziati, permettendo solo
     * i tipi primitivi e le collezioni standard di Java.
     *
     * @param yamlString La stringa YAML da caricare.
     * @return Un oggetto che rappresenta la configurazione caricata. Il tipo esatto
     *         dipenderà dalla struttura del YAML (es. {@code Map<String, Object>},
     *         {@code List<Object>}, {@code String}, {@code Integer}, ecc.).
     * @throws org.yaml.snakeyaml.error.YAMLException Se la stringa YAML contiene
     *         tag non sicuri o è malformata.
     */
    public Object loadConfig(String yamlString) {
        // Utilizza SafeConstructor per prevenire l'istanza di oggetti arbitrari.
        // SafeConstructor permette solo i tag YAML standard e previene l'esecuzione di codice arbitrario
        // che potrebbe derivare dalla deserializzazione di classi Java arbitrarie.
        Constructor constructor = new SafeConstructor();
        Yaml yaml = new Yaml(constructor);

        // Carica la configurazione dalla stringa YAML.
        // Il tipo di ritorno sarà determinato dalla struttura del YAML.
        return yaml.load(yamlString);
    }
}

