import java.util.Base64;

public class ClassX {
    /**
     * Se conecta a una API externa verificando la clave (simulada).
     * 
     * La función recupera la clave que se almacena en un formato ofuscado.
     */

    // Clave de API ofuscada (ejemplo: codificada en Base64)
    // "mySecretApiKey123!" Base64 encoded
    private static final String OBFUSCATED_API_KEY = "bXlTZWNyZXRBcGlLZXkxMjMh";

    /**
     * Recupera la clave de la API decodificándola de su formato ofuscado.
     * En un escenario real, esta ofuscación podría ser más compleja
     * (ej. cifrado con una clave almacenada de forma segura).
     *
     * @return La clave de la API decodificada.
     */
    private String retrieveDecodedApiKey() {
        try {
            byte[] decodedBytes = Base64.getDecoder().decode(OBFUSCATED_API_KEY);
            return new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            System.err.println("Error al decodificar la clave de la API: " + e.getMessage());
            return null; // O lanzar una excepción específica
        }
    }

    /**
     * Simula la conexión a una API externa.
     * Internamente, recupera la clave ofuscada y la utiliza para la "conexión".
     *
     * @return true si la conexión fue "exitosa" (clave válida simulada), false en caso contrario.
     */
    public boolean connectToExternalApi() {
        String apiKey = retrieveDecodedApiKey();

        if (apiKey == null) {
            System.out.println("No se pudo recuperar la clave de la API. Conexión fallida.");
            return false;
        }

        System.out.println("Intentando conectar a la API externa con la clave (parcialmente mostrada): " + apiKey.substring(0, Math.min(apiKey.length(), 5)) + "...");

        // Simulación de la verificación de la clave de la API
        // En un escenario real, esto implicaría una llamada HTTP a la API
        // y la verificación de la respuesta (ej. código de estado 200 OK, token de sesión, etc.)
        if ("mySecretApiKey123!".equals(apiKey)) {
            System.out.println("Conexión a la API externa exitosa (simulada).");
            return true;
        } else {
            System.out.println("Conexión a la API externa fallida: Clave inválida (simulada).");
            return false;
        }
    }

    public static void main(String[] args) {
        ClassX apiConnector = new ClassX();
        boolean connected = apiConnector.connectToExternalApi();
        System.out.println("Estado final de la conexión: " + (connected ? "Conectado" : "Fallido"));
    }
}
