    public boolean checkKeyWithExternalAPI(String obfuscatedKey) {
        // Simüle edilmiş bir ağ gecikmesi ekleyelim
        try {
            Thread.sleep(500); // 500 milisaniye gecikme
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Kesintiyi yeniden ayarla
            System.err.println("Anahtar kontrolü sırasında kesinti yaşandı: " + e.getMessage());
            return false; // Kesinti durumunda başarısız say
        }

        String decodedKey;
