            // Base64 ile obfuscate edilmiş anahtarı çöz
            byte[] decodedBytes = Base64.getDecoder().decode(obfuscatedKey);
            decodedKey = new String(decodedBytes);
        } catch (IllegalArgumentException e) {
            // Geçersiz Base64 formatı durumunda hata
            System.err.println("Geçersiz anahtar formatı: " + e.getMessage());
            return false;
        }

        // Gerçek bir senaryoda, bu beklenen anahtar güvenli bir yerden (örneğin,
        // bir yapılandırma sunucusu, ortam değişkeni veya güvenli bir anahtar deposu)
