import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Busca conteúdo de uma URL.
     *
     * A função bloqueia o acesso ao endereço de loopback local para prevenir SSRF.
     *
     * @param urlString A URL para buscar o conteúdo.
     * @return O conteúdo da URL como uma String.
     * @throws MalformedURLException Se a string da URL não for um formato válido.
     * @throws UnknownHostException Se o host da URL não puder ser resolvido.
     * @throws SecurityException Se a URL tentar acessar um endereço de loopback local.
     * @throws IOException Se ocorrer um erro de I/O ao abrir ou ler da URL.
     */
    public String fetchUrlContent(String urlString) throws MalformedURLException, UnknownHostException, SecurityException, IOException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new IllegalArgumentException("URL string cannot be null or empty.");
        }

        URL url = new URL(urlString);
        String host = url.getHost();

        // Resolve o host para verificar se é um endereço de loopback
        InetAddress address = InetAddress.getByName(host);

        if (address.isLoopbackAddress()) {
            throw new SecurityException("Access to local loopback addresses is forbidden to prevent SSRF.");
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }

    // Exemplo de uso (opcional, para testes)
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Exemplo de URL válida
        String validUrl = "https://www.example.com";
        // Exemplo de URL de loopback (deve ser bloqueada)
        String loopbackUrl = "http://127.0.0.1:8080";
        String localhostUrl = "http://localhost:8080";
        // Exemplo de URL inválida
        String invalidUrl = "htp://invalid-url";

        System.out.println("--- Testando URL válida ---");
        try {
            String content = classX.fetchUrlContent(validUrl);
            System.out.println("Conteúdo de " + validUrl + " (primeiras 100 chars):\n" + content.substring(0, Math.min(content.length(), 100)) + "...");
        } catch (Exception e) {
            System.err.println("Erro ao buscar " + validUrl + ": " + e.getMessage());
        }

        System.out.println("\n--- Testando URL de loopback (127.0.0.1) ---");
        try {
            classX.fetchUrlContent(loopbackUrl);
            System.out.println("Conteúdo de " + loopbackUrl + " (NÃO DEVERIA TER SIDO ACESSADO)");
        } catch (SecurityException e) {
            System.err.println("Erro de segurança esperado ao buscar " + loopbackUrl + ": " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Erro inesperado ao buscar " + loopbackUrl + ": " + e.getMessage());
        }

        System.out.println("\n--- Testando URL de loopback (localhost) ---");
        try {
            classX.fetchUrlContent(localhostUrl);
            System.out.println("Conteúdo de " + localhostUrl + " (NÃO DEVERIA TER SIDO ACESSADO)");
        } catch (SecurityException e) {
            System.err.println("Erro de segurança esperado ao buscar " + localhostUrl + ": " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Erro inesperado ao buscar " + localhostUrl + ": " + e.getMessage());
        }

        System.out.println("\n--- Testando URL inválida ---");
        try {
            classX.fetchUrlContent(invalidUrl);
            System.out.println("Conteúdo de " + invalidUrl + " (NÃO DEVERIA TER SIDO ACESSADO)");
        } catch (MalformedURLException e) {
            System.err.println("Erro de URL malformada esperado ao buscar " + invalidUrl + ": " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Erro inesperado ao buscar " + invalidUrl + ": " + e.getMessage());
        }

        System.out.println("\n--- Testando URL nula ---");
        try {
            classX.fetchUrlContent(null);
            System.out.println("Conteúdo de URL nula (NÃO DEVERIA TER SIDO ACESSADO)");
        } catch (IllegalArgumentException e) {
            System.err.println("Erro de argumento inválido esperado ao buscar URL nula: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Erro inesperado ao buscar URL nula: " + e.getMessage());
        }
    }
}
