    /**
     * Ανακτά περιεχόμενο από μια διεύθυνση URL.
     *
     * Η λειτουργία αποκλείει την πρόσβαση στη διεύθυνση τοπικού βρόχου για να αποτρέψει το SSRF.
     *
     * @param urlString Η διεύθυνση URL από την οποία θα ανακτηθεί το περιεχόμενο.
     * @return Το περιεχόμενο της διεύθυνσης URL ως String.
     * @throws IllegalArgumentException Εάν η διεύθυνση URL είναι άκυρη, ο οικοδεσπότης δεν μπορεί να επιλυθεί,
     *                                  ή οδηγεί σε διεύθυνση τοπικού βρόχου.
     * @throws IOException Εάν προκύψει σφάλμα κατά το άνοιγμα της σύνδεσης ή την ανάγνωση του περιεχομένου.
     */
    public String retrieveContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL format: " + urlString, e);
        }

        // SSRF prevention: Check for loopback address
        InetAddress address;
        try {
            address = InetAddress.getByName(url.getHost());
        } catch (UnknownHostException e) {
            throw new IllegalArgumentException("Unknown host: " + url.getHost(), e);
        }

        if (address.isLoopbackAddress()) {
            throw new IllegalArgumentException("Access to loopback address is blocked for security reasons: " + url.getHost());
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
