     */
    public String getContentFromUrl(String urlString) throws MalformedURLException, IOException, SecurityException {
        URL url = new URL(urlString);
        String host = url.getHost();

        try {
            InetAddress address = InetAddress.getByName(host);
            if (address.isLoopbackAddress()) {
                throw new SecurityException("Acceso denegado: No se permite el acceso a direcciones de bucle invertido (localhost) para prevenir SSRF.");
            }
        } catch (UnknownHostException e) {
            // Si el host no se puede resolver, podría ser un dominio inválido o un problema de red.
            // En este contexto, si no se puede resolver, no es una dirección de bucle invertido explícita.
            // Se podría añadir un log aquí si es necesario.
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
