import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.io.IOException;

public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     * 
     * @param urlString Die URL, von der Inhalte abgerufen werden sollen.
     * @return Der Inhalt der URL als String.
     * @throws MalformedURLException Wenn die URL ungültig ist.
     * @throws IOException Wenn ein E/A-Fehler auftritt.
     * @throws IllegalArgumentException Wenn versucht wird, auf eine Loopback-Adresse zuzugreifen.
     */
    public String fetchUrlContent(String urlString) throws MalformedURLException, IOException, IllegalArgumentException {
        URL url = new URL(urlString);

        // SSRF-Prävention: Überprüfen der Host-Adresse
        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IllegalArgumentException("URL host cannot be empty.");
        }

        InetAddress address = InetAddress.getByName(host);
        if (address.isLoopbackAddress()) {
            throw new IllegalArgumentException("Access to loopback address is forbidden to prevent SSRF.");
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
