import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLConnection;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Ruft Inhalte von einer URL ab.
     * 
     * Die Funktion blockiert den Zugriff auf die lokale Loopback-Adresse, um SSRF zu verhindern.
     *
     * @param urlString Die URL, von der Inhalte abgerufen werden sollen.
     * @return Der Inhalt der URL als String.
     * @throws MalformedURLException Wenn die URL ungültig ist.
     * @throws IOException Wenn ein E/A-Fehler auftritt oder der Zugriff auf eine Loopback-Adresse versucht wird.
     */
    public String fetchUrlContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Invalid URL format: " + urlString + " - " + e.getMessage());
        }

        String host = url.getHost();
        if (host == null || host.trim().isEmpty()) {
            throw new IOException("URL does not contain a valid host.");
        }

        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (addr.isLoopbackAddress()) {
                    throw new IOException("Access to loopback address (" + addr.getHostAddress() + ") is blocked to prevent SSRF.");
                }
            }
        } catch (UnknownHostException e) {
            // This can happen if the host is not resolvable, which is fine for SSRF prevention
            // but might indicate a problem with the URL itself.
            // We can choose to re-throw or let the connection attempt handle it.
            // For now, let the connection attempt fail if the host is truly unreachable.
        }

        StringBuilder content = new StringBuilder();
        URLConnection connection = url.openConnection();

        // Set reasonable timeouts to prevent hanging
        connection.setConnectTimeout(5000); // 5 seconds for connection
        connection.setReadTimeout(10000);   // 10 seconds for reading

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        } catch (IOException e) {
            throw new IOException("Failed to read content from URL: " + urlString + " - " + e.getMessage(), e);
        }

        return content.toString();
    }
}
