import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.InetAddress;
import java.net.MalformedURLException;
import java.io.IOException;

public class ClassX {
    /**
     * Получает содержимое по URL.
     *
     * Функция блокирует доступ к локальному адресу обратной связи, чтобы предотвратить SSRF.
     *
     * @param urlString Строка URL, содержимое которой нужно получить.
     * @return Содержимое URL в виде строки.
     * @throws IllegalArgumentException Если URL имеет неверный формат или указывает на адрес обратной связи.
     * @throws IOException Если произошла ошибка ввода-вывода при получении содержимого.
     */
    public String fetchUrlContent(String urlString) throws IOException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL format: " + urlString, e);
        }

        // SSRF prevention: Check if the host resolves to a loopback address
        InetAddress address;
        try {
            address = InetAddress.getByName(url.getHost());
        } catch (java.net.UnknownHostException e) {
            // If the host cannot be resolved, it's an issue preventing connection.
            // It also means it's not a known loopback address, but we can't connect anyway.
            throw new IOException("Could not resolve host: " + url.getHost(), e);
        }

        if (address.isLoopbackAddress()) {
            throw new IllegalArgumentException("Access to loopback address is blocked to prevent SSRF: " + url.getHost());
        }

        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
        }
        return content.toString();
    }
}
