     * @throws SecurityException URL'nin ana bilgisayarı bir döngü geri adresi ise.
     */
    public String getContentFromUrl(String urlString) throws IOException, SecurityException {
        URL url;
        try {
            url = new URL(urlString);
        } catch (MalformedURLException e) {
            throw new MalformedURLException("Geçersiz URL formatı: " + urlString);
        }

        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            throw new MalformedURLException("URL'de ana bilgisayar adı bulunamadı: " + urlString);
        }

        try {
            InetAddress address = InetAddress.getByName(host);
